insert_marker = "        # being compared, but with different case.\n"
if insert_marker not in text:
    raise SystemExit('insert marker not found')

helper = """

        def _table_value_differs(va, vb):
            """Return `True` if two table cell values differ.

            This is used primarily to safely compare variable-length-array (VLA)
            columns, for which each row may contain an ndarray.
            """
            if isinstance(va, np.ndarray) or isinstance(vb, np.ndarray):
                if not (isinstance(va, np.ndarray) and isinstance(vb, np.ndarray)):
                    return True
                if va.shape != vb.shape:
                    return True
                if np.issubdtype(va.dtype, np.number) and np.issubdtype(
                    vb.dtype, np.number
                ):
                    return where_not_allclose(va, vb, rtol=self.rtol, atol=self.atol)[
                        0
                    ].size > 0
                return not np.array_equal(va, vb)

            if np.isscalar(va) and np.isscalar(vb):
                return diff_values(va, vb, rtol=self.rtol, atol=self.atol)

            return va != vb
"""

# insert helper before that marker (i.e., after the previous line)
text = text.replace(insert_marker, helper + insert_marker)

old = """            if np.issubdtype(arra.dtype, np.floating) and np.issubdtype(
                arrb.dtype, np.floating
            ):
                diffs = where_not_allclose(arra, arrb, rtol=self.rtol, atol=self.atol)
            elif \"P\" in col.format:
                diffs = (
                    [
                        idx
                        for idx in range(len(arra))
                        if not np.allclose(
                            arra[idx], arrb[idx], rtol=self.rtol, atol=self.atol
                        )
                    ],
                )
            else:
                diffs = np.where(arra != arrb)
"""

new = """            if np.issubdtype(arra.dtype, np.floating) and np.issubdtype(
                arrb.dtype, np.floating
            ):
                diffs = where_not_allclose(arra, arrb, rtol=self.rtol, atol=self.atol)
            elif getattr(col.format, "format", None) in ("P", "Q"):
                # Variable-length arrays (VLA) are stored as object arrays where
                # each element is a numpy array.  Comparing these with ``!=`` can
                # raise exceptions (or produce incorrect results), so compare
                # row-by-row instead.
                diffs = (
                    [
                        idx
                        for idx in range(len(arra))
                        if _table_value_differs(arra[idx], arrb[idx])
                    ],
                )
            else:
                try:
                    diffs = np.where(arra != arrb)
                except ValueError:
                    # Fall back to a safe row-by-row comparison for object-dtype
                    # columns containing array-like elements.
                    diffs = (
                        [
                            idx
                            for idx in range(len(arra))
                            if _table_value_differs(arra[idx], arrb[idx])
                        ],
                    )
"""

if old not in text:
    raise SystemExit('target comparison block not found')
text = text.replace(old, new)

path.write_text(text, encoding='utf-8')
print('patched', path)
